/**
 * The git boundary (docs/AGENT-GUARD.md): pre-commit, commit-msg and pre-push call the SAME decision path as every other boundary. They are bash
 * scripts that `source` hook.sh (builtins only: no node, no curl, no git call of their own); the daemon runs git itself, warm, and caches its verdict
 * by blob hash. `kit agent-guard sync` writes them to .githooks/ and points core.hooksPath at it; an agent may not change core.hooksPath or pass
 * --no-verify (rule git-skip-hooks). Fail closed: an unreachable daemon exits non-zero.
 */
export const GITHOOKS_DIR = ".githooks";
export const GENERATED_LINE = "# generated by `kit agent-guard sync` from constitution.rules.json: never edit by hand (docs/AGENT-GUARD.md)";
/** The repository's own pre-push gate (npm test on the pushed commit): when it exists, the generated pre-push runs the guard first and then hands the pushed refs to it. */
export const PROJECT_PRE_PUSH_GATE = "packages/cli/scripts/pre-push.mjs";
/** { path: text } for the guard pack whose daemon.mjs is at `daemonRel` (relative to the repository root); `prePushGate`: the repository has its own pre-push gate to chain after the guard. */
export function gitHookFiles(daemonRel, { prePushGate = false } = {}) {
  const dir = daemonRel.replace(/\/[^/]+$/, "");
  const head = (which) => `#!/bin/bash\n${GENERATED_LINE}\nROOT="\${0%/*}/.."\nCLAUDE_PROJECT_DIR="$(cd "$ROOT" && pwd)"; export CLAUDE_PROJECT_DIR\n`;
  const body = (which) => `${head(which)}set -- git ${which} "$@"\n. "$ROOT/${dir}/hook.sh"\n`;
  // git writes the pushed refs to stdin, once: read them, give the guard its copy in a subshell (its exit, and its daemon cleanup, end there), then restore them for the gate
  const pushBody = () => `${head("pre-push")}IN="$(cat)"\n( set -- git pre-push "$@"; . "$ROOT/${dir}/hook.sh" ) <<<"$IN" || exit $?\nexec 0<<<"$IN"\ncd "$ROOT" || exit 1\nexec node ${PROJECT_PRE_PUSH_GATE} "$@"\n`;
  return { [`${GITHOOKS_DIR}/pre-commit`]: body("pre-commit"), [`${GITHOOKS_DIR}/commit-msg`]: body("commit-msg"), [`${GITHOOKS_DIR}/pre-push`]: prePushGate ? pushBody() : body("pre-push") };
}
